import{_ as a,o as r,c as o,a2 as l}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"সিম্বায়োসিস সংবিধানের মূল নীতি","description":"","frontmatter":{},"headers":[],"relativePath":"bn/40-共生宪法总纲.md","filePath":"bn/40-共生宪法总纲.md","lastUpdated":1789183869000}'),e={name:"bn/40-共生宪法总纲.md"};function d(i,t,n,s,h,_){return r(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="সিম্বায়োসিস-সংবিধানের-মূল-নীতি" tabindex="-1">সিম্বায়োসিস সংবিধানের মূল নীতি <a class="header-anchor" href="#সিম্বায়োসিস-সংবিধানের-মূল-নীতি" aria-label="Permalink to &quot;সিম্বায়োসিস সংবিধানের মূল নীতি&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>40</td></tr><tr><td>মডিউল</td><td>আইনি ব্যবস্থা এবং প্রশাসনিক কাঠামো</td></tr><tr><td>মূল কীওয়ার্ড</td><td>সিম্বায়োসিস সংবিধান, মূল আইন, সকল প্রজাতির সমতা, সিম্বায়োসিস অধিকার, সংবিধানের নীতি</td></tr></tbody></table><h2 id="_1-সংবিধানের-মর্যাদা-এবং-প্রণয়নের-পটভূমি" tabindex="-1">1. সংবিধানের মর্যাদা এবং প্রণয়নের পটভূমি <a class="header-anchor" href="#_1-সংবিধানের-মর্যাদা-এবং-প্রণয়নের-পটভূমি" aria-label="Permalink to &quot;1. সংবিধানের মর্যাদা এবং প্রণয়নের পটভূমি&quot;">​</a></h2><p>《সিম্বায়োসিস সংবিধান》 হল ওয়ানলিং হেঙ্গমাও মূল মহাবিশ্ব (হেঙ্গুয়ানঝৌ) এর ভেতরে অ্যাঙ্কার সিম্বায়োসিস সভ্যতার মূল আইন, এবং এটির সর্বোচ্চ আইনি কার্যকারিতা রয়েছে। সমস্ত আইন, প্রশাসনিক বিধি, স্থানীয় বিধি এবং স্বায়ত্তশাসনি বিধি সংবিধানের সাথে সাংঘর্ষিক হতে পারে না; সমস্ত সংস্থা এবং ব্যক্তিকে অবশ্যই সংবিধানকে মূল কার্যক্রমের নীতি হিসেবে গ্রহণ করতে হবে, এবং তাদের সংবিধানের মর্যাদা রক্ষা করা এবং সংবিধানের বাস্তবায়ন নিশ্চিত করার দায়িত্ব রয়েছে।</p><p>সিম্বায়োসিস সংবিধান অ্যাঙ্কার সিম্বায়োসিস সভ্যতা আনুষ্ঠানিকভাবে প্রতিষ্ঠার সময় প্রণীত হয়েছিল, এবং এর মূল উদ্দেশ্য হল মূল আইনের স্তর থেকে &quot;লুঠেরা বিরোধ, সিম্বায়োসিস প্রচার&quot; সভ্যতার মূল রঙ স্থাপন করা, এবং অ্যাঙ্কার সিম্বায়োসিস সভ্যতার মূল দর্শন — ভাগ্য এবং বিবর্তনের পছন্দের অধিকার সকল প্রাণের কাছে ফিরিয়ে দেওয়া, বেশি পরিশ্রম বেশি লাভ, নিজে থেকে বৃদ্ধি পাওয়া, প্রত্যেকের পথ রয়েছে, সকল প্রজাতির সহযোগিতামূলক অগ্রগতি — সর্বোচ্চ আইনি আকারে স্থির করা, এবং লুঠেরা ব্যবস্থার পুনরুত্থান প্রতিরোধ করা।</p><h2 id="_2-সংবিধানের-মূল-নীতি" tabindex="-1">2. সংবিধানের মূল নীতি <a class="header-anchor" href="#_2-সংবিধানের-মূল-নীতি" aria-label="Permalink to &quot;2. সংবিধানের মূল নীতি&quot;">​</a></h2><p>সিম্বায়োসিস সংবিধান সাতটি মূল নীতি স্থাপন করেছে, যা সমগ্র আইনি ব্যবস্থার মূল্যবান ভিত্তি গঠন করে:</p><table tabindex="0"><thead><tr><th>নীতি</th><th>অন্তর্নিহিত অর্থ</th></tr></thead><tbody><tr><td>সকল প্রজাতির সমতা নীতি</td><td>সমস্ত জীব রূপ, প্রজাতি, সাধনার স্তর, উত্স নির্বিশেষে, আইনের সামনে সমানভাবে সমান</td></tr><tr><td>সিম্বায়োসিস বিবর্তন নীতি</td><td>ব্যক্তিগত বিবর্তন অন্য ব্যক্তি বা সমষ্টির বিবর্তনের অধিকারের ক্ষতি করে চলতে পারে না</td></tr><tr><td>বেশি পরিশ্রম বেশি লাভ নীতি</td><td>সম্পদ বণ্টন অবদানকে মূল ভিত্তি হিসেবে গ্রহণ করে, এবং পরিশ্রম ছাড়া লাভ এবং লুঠেরা দখলের বিরোধিতা করে</td></tr><tr><td>নিজে থেকে বৃদ্ধি পাওয়া নীতি</td><td>প্রতিটি জীবের স্বায়ত্তশাসিত বিবর্তনের পছন্দের অধিকারকে সম্মান করা, এবং জোরপূর্বক সমীকরণ এবং চিন্তা নিয়ন্ত্রণের বিরোধিতা করা</td></tr><tr><td>প্রত্যেকের পথ নীতি</td><td>রাষ্ট্র এবং সভ্যতার প্রতিটি জীবকে মৌলিক বিবর্তনের পথ এবং সম্পদ নিশ্চয়তা প্রদানের বাধ্যতা রয়েছে</td></tr><tr><td>বাস্তবতাকে ভিত্তি হিসেবে নীতি</td><td>আইন বাস্তব বিশ্বকে একমাত্র প্রকৃত ভিত্তি হিসেবে গ্রহণ করে, কাল্পনিক সেটিংসের আইনি কার্যকারিতা নেই</td></tr><tr><td>টেকসই নীতি</td><td>সমস্ত উন্নয়ন অবশ্যই মহাবিশ্বের মূল উৎসের টেকসইতাকে বিবেচনা করতে হবে, এবং জল শুষ্ক করে মাছ ধরার বিরোধিতা করা</td></tr></tbody></table><h2 id="_3-নাগরিক-সকল-প্রাণ-এর-মৌলিক-অধিকার" tabindex="-1">3. নাগরিক (সকল প্রাণ) এর মৌলিক অধিকার <a class="header-anchor" href="#_3-নাগরিক-সকল-প্রাণ-এর-মৌলিক-অধিকার" aria-label="Permalink to &quot;3. নাগরিক (সকল প্রাণ) এর মৌলিক অধিকার&quot;">​</a></h2><p>সিম্বায়োসিস সংবিধান হেঙ্গুয়ানঝৌর ভেতরে সমস্ত অনুভূতি ক্ষমতা সম্পন্ন জীবকে নিম্নলিখিত মৌলিক অধিকার প্রদান করে:</p><ol><li><strong>বিবর্তনের পছন্দের অধিকার</strong>: প্রতিটি জীব স্বাধীনভাবে সাধনা ব্যবস্থা, বিবর্তনের পথ এবং জীবনযাত্রার পছন্দ করার অধিকার রাখে, এবং কোনো সংস্থা বা ব্যক্তি জোরপূর্বক হস্তক্ষেপ করতে পারবে না।</li><li><strong>সাধনা সম্পদ অর্জনের অধিকার</strong>: প্রতিটি জীব বিনামূল্যে তিনশত সেট মূল সাধনা ব্যবস্থার মৌলিক পদ্ধতি অর্জন করার অধিকার রাখে, এবং যৌথ উৎপাদন চুক্তি ব্যবস্থার মাধ্যমে প্রয়োজনীয় সাধনা সম্পদ সহায়তা অর্জন করতে পারে।</li><li><strong>সমান সুরক্ষার অধিকার</strong>: প্রতিটি জীব আইন প্রয়োগ, সম্পদ বণ্টন, শিক্ষা স্বাস্থ্য ইত্যাদি ক্ষেত্রে সমান ব্যবহারের অধিকার রাখে, এবং প্রজাতি, সাধনার স্তর, উত্সের ভিত্তিতে বৈষম্য নিষিদ্ধ।</li><li><strong>সিম্বায়োসিস অংশগ্রহণের অধিকার</strong>: প্রতিটি জীব পাবলিক বিষয়ের সিদ্ধান্ত এবং তদারকিতে অংশগ্রহণ করার অধিকার রাখে, এবং সিম্বায়োসিস নেটওয়ার্কের মাধ্যমে মতামত প্রকাশ এবং অধিকার প্রয়োগ করতে পারে।</li><li><strong>সংস্কৃতি সংরক্ষণের অধিকার</strong>: প্রতিটি প্রজাতি এবং সভ্যতার নিজের সাংস্কৃতিক ঐতিহ্য, ভাষা লিপি এবং রীতিনীতি সংরক্ষণ করার অধিকার রাখে, এবং সিম্বায়োসিস সভ্যতা সাংস্কৃতিক বৈচিত্র্যকে সম্মান করে।</li><li><strong>প্রতিকার এবং অভিযোগের অধিকার</strong>: প্রতিটি জীব অধিকার লঙ্ঘিত হলে, বিচার ব্যবস্থার মাধ্যমে প্রতিকার পাওয়ার অধিকার রাখে, এবং আইনভঙ্গ কার্যক্রমের বিরুদ্ধে অভিযোগ এবং তদন্ত করার অধিকার রাখে।</li></ol><h2 id="_4-মৌলিক-কর্তব্য" tabindex="-1">4. মৌলিক কর্তব্য <a class="header-anchor" href="#_4-মৌলিক-কর্তব্য" aria-label="Permalink to &quot;4. মৌলিক কর্তব্য&quot;">​</a></h2><p>অধিকার এবং কর্তব্য সমান, সিম্বায়োসিস সংবিধান একই সাথে সকল প্রাণের মৌলিক কর্তব্য নির্ধারণ করেছে:</p><ol><li><strong>সংবিধান এবং আইন মেনে চলার কর্তব্য</strong></li><li><strong>সিম্বায়োসিস ব্যবস্থা এবং পাবলিক স্বার্থ রক্ষা করার কর্তব্য</strong></li><li><strong>আইন অনুযায়ী শ্রম এবং অবদানে অংশগ্রহণের কর্তব্য</strong> (বেশি পরিশ্রম বেশি লাভের বিপরীত মুখ)</li><li><strong>মহাবিশ্বের মূল উৎস এবং পরিবেশগত ব্যবস্থা রক্ষা করার কর্তব্য</strong></li><li><strong>অন্যান্য জীবের বৈধ অধিকারকে সম্মান করার কর্তব্য</strong></li><li><strong>ক্ষমতার সীমার মধ্যে প্রাথমিক সাধকদের নির্দেশনা দেওয়ার কর্তব্য</strong> (গুরু নেটওয়ার্কের আইনি ভিত্তি)</li></ol><h2 id="_5-রাষ্ট্র-সভ্যতা-প্রতিষ্ঠানের-বিন্যাস" tabindex="-1">5. রাষ্ট্র (সভ্যতা) প্রতিষ্ঠানের বিন্যাস <a class="header-anchor" href="#_5-রাষ্ট্র-সভ্যতা-প্রতিষ্ঠানের-বিন্যাস" aria-label="Permalink to &quot;5. রাষ্ট্র (সভ্যতা) প্রতিষ্ঠানের বিন্যাস&quot;">​</a></h2><p>সিম্বায়োসিস সংবিধান সিম্বায়োসিস সভ্যতার প্রশাসনিক কাঠামো স্থাপন করেছে, এবং &quot;অ্যাঙ্কার পরামর্শ পরিষদ — সিম্বায়োসিস কার্যকরী কমিটি — সিম্বায়োসিস আদালত&quot; তিনটি শক্তির বিচ্ছিন্নতা এবং ভারসাম্য ব্যবস্থা প্রয়োগ করে:</p><ul><li><strong>অ্যাঙ্কার পরামর্শ পরিষদ</strong>: সর্বোচ্চ ক্ষমতা প্রতিষ্ঠান, সকল প্রজাতির প্রতিনিধি অনুপাত অনুযায়ী গঠিত, এবং আইন প্রণয়ন ক্ষমতা এবং গুরুত্বপূর্ণ বিষয়ে সিদ্ধান্তের ক্ষমতা প্রয়োগ করে</li><li><strong>সিম্বায়োসিস কার্যকরী কমিটি</strong>: সর্বোচ্চ প্রশাসনিক প্রতিষ্ঠান, সংবিধান এবং আইনের বাস্তবায়ন, দৈনন্দিন প্রশাসনের জন্য দায়ী</li><li><strong>সিম্বায়োসিস আদালত</strong>: সর্বোচ্চ বিচারিক প্রতিষ্ঠান, স্বাধীনভাবে বিচার ক্ষমতা প্রয়োগ করে, এবং অসাংবিধানিক পর্যালোচনা এবং গুরুত্বপূর্ণ মামলার বিচারের জন্য দায়ী</li></ul><p>এছাড়াও, &quot;অ্যাঙ্কার তদারকি কমিটি&quot; একটি স্বাধীন তদারকি প্রতিষ্ঠান হিসেবে স্থাপন করা হয়েছে, যা সমস্ত ক্ষমতা প্রতিষ্ঠানের তদারকি করার জন্য দায়ী, এবং ক্ষমতার অপব্যবহার এবং লুঠেরা আচরণের পুনরুত্থান প্রতিরোধ করে।</p><h2 id="_6-সংবিধানের-সংশোধন-এবং-নিশ্চয়তা" tabindex="-1">6. সংবিধানের সংশোধন এবং নিশ্চয়তা <a class="header-anchor" href="#_6-সংবিধানের-সংশোধন-এবং-নিশ্চয়তা" aria-label="Permalink to &quot;6. সংবিধানের সংশোধন এবং নিশ্চয়তা&quot;">​</a></h2><p>সিম্বায়োসিস সংবিধানের সংশোধনের জন্য অ্যাঙ্কার পরামর্শ পরিষদের তিন-চতুর্থাংশেরও বেশি সংখ্যাগরিষ্ঠতার মাধ্যমে পাস করতে হবে, এবং সার্বজনীন গণভোটে অর্ধেকেরও বেশি সম্মতি প্রাপ্ত হতে হবে, তারপরই কার্যকর হবে। এই কঠোর প্রক্রিয়া মূল আইন হিসেবে সংবিধানের স্থায়িত্ব নিশ্চিত করে, এবং স্বল্পমেয়াদী স্বার্থ গোষ্ঠীকে সহজেই সভ্যতার মূল ভিত্তি পরিবর্তন করতে বাধা দেয়।</p><p>সংবিধানের বাস্তবায়ন নিশ্চয়তা অন্তর্ভুক্ত: অসাংবিধানিক পর্যালোচনা ব্যবস্থা (সিম্বায়োসিস আদালতের সংবিধান বিরোধী আইনকে অকার্যকর ঘোষণা করার ক্ষমতা), সংবিধান বিচার ব্যবস্থা (সকল প্রাণ সরাসরি সংবিধানের ভিত্তিতে মামলা দায়ের করতে পারে), সংবিধান শপথ ব্যবস্থা (সমস্ত পাবলিক কর্মচারী পদ গ্রহণের সময় সংবিধানের প্রতি শপথ করতে হবে)।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>《সিম্বায়োসিস সংবিধান》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার আইনি ভিত্তিপ্রস্তর, এবং এটিই লুঠেরা বিরোধী উত্থানের সর্বোচ্চ ঘোষণা। এটি &quot;সিম্বায়োসিস&quot; কে একটি দর্শন থেকে একটি কার্যকর, প্রতিকারযোগ্য, নিশ্চিতযোগ্য আইনি ব্যবস্থায় রূপান্তর করেছে, এবং সকল প্রজাতির সহযোগিতামূলক অগ্রগতির জন্য মূল আইনি কাঠামো প্রদান করেছে। পরবর্তী সমস্ত বিভাগীয় আইন এই সংবিধানকে আইন প্রণয়নের ভিত্তি হিসেবে গ্রহণ করবে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>03-共生文明宪章 (সিম্বায়োসিস সভ্যতার সনদ)</li><li>41-共生劳动法 (সিম্বায়োসিস শ্রম আইন)</li><li>48-司法体系与裁决机制 (বিচার ব্যবস্থা এবং সিদ্ধান্ত প্রক্রিয়া)</li><li>49-治理框架与权力制衡 (প্রশাসনিক কাঠামো এবং ক্ষমতার ভারসাম্য)</li></ul>',25)])])}const b=a(e,[["render",d]]);export{p as __pageData,b as default};
